// Service worker: cache the whole app on the first visit; then work fully offline.
// sw-files.js (generated by tools/build_sw_list.py) defines FMT_VERSION and FMT_FILES.
/* global importScripts, FMT_VERSION, FMT_FILES */
importScripts('sw-files.js');
const CACHE = 'fmt-' + self.FMT_VERSION;

function notify(msg) {
  return self.clients.matchAll({ includeUncontrolled: true }).then((cs) => cs.forEach((c) => c.postMessage(msg)));
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE)
      .then((c) => c.addAll(self.FMT_FILES.map((f) => new Request(f, { cache: 'reload' }))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.indexOf('fmt-') === 0 && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
      .then(() => notify({ type: 'cached', version: self.FMT_VERSION })),
  );
});

// Cache first (instant, offline), refresh from the network in the background.
self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // the app makes no third-party requests
  event.respondWith(
    caches.open(CACHE).then((cache) =>
      cache.match(req, { ignoreSearch: true }).then((hit) => {
        const net = fetch(req)
          .then((res) => {
            if (res && res.ok && res.type === 'basic') cache.put(req, res.clone());
            return res;
          })
          .catch(() => hit || (req.mode === 'navigate' ? cache.match('index.html') : Response.error()));
        if (hit) { event.waitUntil(net.catch(() => null)); return hit; }
        return net;
      })),
  );
});

self.addEventListener('message', (event) => {
  if (event.data === 'status') {
    caches.open(CACHE)
      .then((c) => c.keys())
      .then((keys) => event.source && event.source.postMessage({ type: 'status', ready: keys.length >= self.FMT_FILES.length, version: self.FMT_VERSION }));
  }
});
